        get: { (
            uniffiHandle: UInt64,
            request: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> AutoEqFetchResponse in
                guard let uniffiObj = try? FfiConverterTypeAutoEqFetch.handleMap.get(handle: uniffiHandle) else {
