        /**
         * B's snapshot name ("" with no compare).
         */bName: String, 
        /**
         * What this call recalled, if it recalled anything.
         */recall: SnapshotRecall?) {
        self.active = active
        self.side = side
        self.aName = aName
        self.bName = bName
        self.recall = recall
    }
}

