    public static func ==(lhs: BiquadSection, rhs: BiquadSection) -> Bool {
        if lhs.b0 != rhs.b0 {
            return false
        }
        if lhs.b1 != rhs.b1 {
            return false
        }
        if lhs.b2 != rhs.b2 {
            return false
        }
        if lhs.a1 != rhs.a1 {
            return false
        }
        if lhs.a2 != rhs.a2 {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(b0)
        hasher.combine(b1)
        hasher.combine(b2)
        hasher.combine(a1)
