    public static func ==(lhs: LinkSecurity, rhs: LinkSecurity) -> Bool {
        if lhs.encrypted != rhs.encrypted {
            return false
        }
        if lhs.local != rhs.local {
            return false
        }
        if lhs.hubKey != rhs.hubKey {
