/**
 * A hub as its DNS-SD TXT record describes it ([`crate::link_parse_txt`]),
 * before an address is resolved.
 */
public struct LinkTxtRecord {
    /**
     * The `hid`, lowercase.
     */
    public var hubId: String
    /**
     * The instance name, safe to show (the `hid` when it has none).
     */
    public var name: String
    /**
     * `console`, `bridge` or `unknown`.
     */
    public var kind: String
    /**
     * `none` or `pin`.
     */
    public var auth: String
    /**
     * Devices the hub shares.
     */
    public var deviceCount: UInt32
    /**
     * Their serials, when the hub lists them.
     */
    public var serials: [String]
    /**
     * The WebSocket path.
     */
    public var path: String
    /**
     * The record carried `tls=1`: the hub says its port speaks TLS. A hint
     * (anyone on the LAN can forge or strip it) for the connect's
     * `tls_advertised`, the "advertised TLS never falls back" rule; false
     * for an upstream hub.
     */
    public var tlsAdvertised: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The `hid`, lowercase.
         */hubId: String, 
        /**
         * The instance name, safe to show (the `hid` when it has none).
         */name: String, 
        /**
         * `console`, `bridge` or `unknown`.
         */kind: String, 
        /**
         * `none` or `pin`.
         */auth: String, 
        /**
         * Devices the hub shares.
         */deviceCount: UInt32, 
        /**
         * Their serials, when the hub lists them.
         */serials: [String], 
        /**
         * The WebSocket path.
         */path: String, 
        /**
         * The record carried `tls=1`: the hub says its port speaks TLS. A hint
         * (anyone on the LAN can forge or strip it) for the connect's
         * `tls_advertised`, the "advertised TLS never falls back" rule; false
         * for an upstream hub.
         */tlsAdvertised: Bool) {
        self.hubId = hubId
        self.name = name
        self.kind = kind
        self.auth = auth
        self.deviceCount = deviceCount
        self.serials = serials
        self.path = path
        self.tlsAdvertised = tlsAdvertised
    }
}

