    public static func ==(lhs: MeasureSystemApplied, rhs: MeasureSystemApplied) -> Bool {
        if lhs.stage != rhs.stage {
            return false
        }
        if lhs.revisionBefore != rhs.revisionBefore {
            return false
        }
        if lhs.revisionAfter != rhs.revisionAfter {
