        self.arrivals = arrivals
        self.withheld = withheld
        self.transitions = transitions
        self.sumCheckNeeded = sumCheckNeeded
        self.withdrawn = withdrawn
        self.offered = offered
        self.mayApply = mayApply
        self.notice = notice
        self.guardS = guardS
        self.guardNote = guardNote
    }
}

