         */populated: UInt64, 
        /**
         * Valid entries in `bins_db`.
         */binsCount: UInt16, 
        /**
         * The channel the bins belong to.
         */binsChannel: UInt8, 
        /**
         * Sample rate the bins were taken at, in Hz.
         */binsSampleRate: UInt32, 
        /**
         * Raw FFT bins in dBFS.
         */binsDb: [Float], 
        /**
         * The analyser is running on the device.
         */running: Bool, 
        /**
         * Channels the device is measuring.
         */liveCount: UInt8, 
        /**
         * Mask of the channels the device is measuring.
         */liveMask: UInt16, 
        /**
         * Analyser frames per second.
         */framesPerS: UInt16, 
        /**
         * Processor time spent per second, in µs.
         */busyUsPerS: UInt16, 
        /**
         * Time of the last frame, in µs.
         */lastFrameUs: UInt16, 
        /**
         * Processor time the bass bank spends per second, in µs.
         */bassBusyUsPerS: UInt16, 
        /**
         * Device sample rate in Hz.
         */sampleRate: UInt32, 
        /**
         * First band with data; 0xFF when unknown.
         */firstBand: UInt8, 
        /**
         * FFT order in use.
         */fftOrder: UInt8, 
        /**
         * The device refused the requested configuration.
         */configRejected: Bool, 
        /**
         * How often the view should poll, in seconds.
         */refreshIntervalS: Float) {
        self.version = version
        self.telemetryVersion = telemetryVersion
        self.tap = tap
        self.count = count
        self.frames = frames
        self.populated = populated
        self.binsCount = binsCount
        self.binsChannel = binsChannel
        self.binsSampleRate = binsSampleRate
        self.binsDb = binsDb
        self.running = running
        self.liveCount = liveCount
        self.liveMask = liveMask
        self.framesPerS = framesPerS
        self.busyUsPerS = busyUsPerS
        self.lastFrameUs = lastFrameUs
        self.bassBusyUsPerS = bassBusyUsPerS
        self.sampleRate = sampleRate
        self.firstBand = firstBand
        self.fftOrder = fftOrder
        self.configRejected = configRejected
        self.refreshIntervalS = refreshIntervalS
    }
